import React, { useState } from 'react';

const IssueTable = ({ issues }) => {
  return (
    <table className="issue-table">
      <thead>
        <tr>
          <th>Title</th>
          <th>Status</th>
          <th>Date</th>
        </tr>
      </thead>
      <tbody>
        {issues.map((issue) => (
          <tr key={issue.id}>
            <td>{issue.title}</td>
            <td>
              <span className={`status-badge ${issue.status.toLowerCase().replace(' ', '-')}`}>
                {issue.status}
              </span>
            </td>
            <td>{issue.date}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
};

export default IssueTable;
